import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { authService } from '../services/api';

const Login = () => {
  const [formData, setFormData] = useState({
    correoElectronico: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const response = await authService.login(
        formData.correoElectronico,
        formData.password
      );
      
      console.log('Login exitoso:', response);
      
      if (response.user.tipo === 'funcionario') {
        navigate('/funcionario');
      } else {
        navigate('/dashboard');
      }
      
    } catch (error) {
      setError(error.message || 'Error al iniciar sesión');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <style>
        {`
          * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
          }

          body {
            font-family: 'Segoe UI', 'Roboto', 'Helvetica Neue', sans-serif;
          }

          .login-container {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: linear-gradient(135deg, #e8f5e9 0%, #c8e6d9 100%);
            padding: 20px;
          }

          .login-card {
            background: white;
            border-radius: 32px;
            padding: 48px 40px;
            width: 100%;
            max-width: 460px;
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08), 0 8px 20px rgba(0, 100, 60, 0.1);
            transition: transform 0.2s ease, box-shadow 0.2s ease;
          }

          .login-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 28px 48px rgba(0, 0, 0, 0.12), 0 12px 28px rgba(0, 100, 60, 0.15);
          }

          .logo-wrapper {
            text-align: center;
            margin-bottom: 32px;
          }

          .logo {
            width: 130px;
            height: auto;
            display: inline-block;
            filter: drop-shadow(0 4px 6px rgba(0,0,0,0.05));
          }

          .title {
            text-align: center;
            color: #00643C;
            font-size: 28px;
            font-weight: 700;
            margin-bottom: 32px;
            letter-spacing: -0.3px;
          }

          .error-alert {
            background-color: #ffebee;
            border-left: 4px solid #d32f2f;
            color: #b71c1c;
            padding: 14px 18px;
            border-radius: 16px;
            margin-bottom: 28px;
            font-size: 14px;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 10px;
          }

          .error-alert::before {
            content: "⚠️";
            font-size: 18px;
          }

          .form-group {
            margin-bottom: 24px;
          }

          .form-label {
            display: block;
            margin-bottom: 8px;
            color: #1e2a3e;
            font-weight: 600;
            font-size: 14px;
            letter-spacing: 0.3px;
          }

          .input-wrapper {
            position: relative;
            display: flex;
            align-items: center;
          }

          .input-icon {
            position: absolute;
            left: 16px;
            color: #9aa6b5;
            font-size: 18px;
            pointer-events: none;
          }

          .form-input {
            width: 100%;
            padding: 14px 16px 14px 48px;
            border: 1.5px solid #e2e8f0;
            border-radius: 24px;
            font-size: 15px;
            font-family: inherit;
            transition: all 0.2s ease;
            background-color: #fefefe;
            outline: none;
          }

          .form-input:focus {
            border-color: #00643C;
            box-shadow: 0 0 0 3px rgba(0, 100, 60, 0.2);
            background-color: #fff;
          }

          .login-button {
            width: 100%;
            background-color: #00643C;
            color: white;
            padding: 14px;
            border: none;
            border-radius: 40px;
            font-size: 16px;
            font-weight: 700;
            cursor: pointer;
            margin-top: 12px;
            margin-bottom: 28px;
            transition: all 0.2s ease;
            font-family: inherit;
            letter-spacing: 0.5px;
            box-shadow: 0 2px 6px rgba(0, 100, 60, 0.2);
          }

          .login-button:hover:not(:disabled) {
            background-color: #004d2e;
            transform: translateY(-1px);
            box-shadow: 0 8px 18px rgba(0, 100, 60, 0.25);
          }

          .login-button:active:not(:disabled) {
            transform: translateY(1px);
          }

          .login-button:disabled {
            background-color: #9bb7a8;
            cursor: not-allowed;
            transform: none;
            box-shadow: none;
          }

          .links-container {
            text-align: center;
          }

          .forgot-link {
            display: inline-block;
            color: #00643C;
            text-decoration: none;
            font-size: 14px;
            font-weight: 500;
            margin-bottom: 20px;
            transition: color 0.2s;
          }

          .forgot-link:hover {
            color: #004d2e;
            text-decoration: underline;
          }

          .register-text {
            color: #4b5563;
            font-size: 14px;
          }

          .register-link {
            color: #00643C;
            text-decoration: none;
            font-weight: 700;
            margin-left: 6px;
            transition: all 0.2s;
          }

          .register-link:hover {
            color: #004d2e;
            text-decoration: underline;
          }

          /* separador sutil */
          .divider {
            margin: 20px 0 16px;
            border-top: 1px solid #eef2f6;
          }
        `}
      </style>

      <div className="login-container">
        <div className="login-card">
          <div className="logo-wrapper">
            <img 
              src="/logosena.png" 
              alt="Logo SENA" 
              className="logo"
            />
          </div>

          <h2 className="title">Iniciar Sesión</h2>
          
          {error && (
            <div className="error-alert">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label className="form-label">Correo electrónico</label>
              <div className="input-wrapper">
                <span className="input-icon">📧</span>
                <input
                  type="email"
                  name="correoElectronico"
                  value={formData.correoElectronico}
                  onChange={handleChange}
                  required
                  className="form-input"
                  placeholder="tucorreo@ejemplo.com"
                />
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Contraseña</label>
              <div className="input-wrapper">
                <span className="input-icon">🔒</span>
                <input
                  type="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  required
                  className="form-input"
                  placeholder="********"
                />
              </div>
            </div>

            <button 
              type="submit" 
              disabled={loading}
              className="login-button"
            >
              {loading ? 'Iniciando sesión...' : 'INICIAR SESIÓN'}
            </button>

            <div className="links-container">
              <Link to="/recuperar-password" className="forgot-link">
                ¿Olvidaste tu contraseña?
              </Link>
              
              <div className="divider"></div>
              
              <div className="register-text">
                ¿No tienes una cuenta?
                <Link to="/registro" className="register-link">
                  Registrarte aquí
                </Link>
              </div>
            </div>
          </form>
        </div>
      </div>
    </>
  );
};

export default Login;
